package com.csust.eyediagnosis.workflow.inference;

import com.alibaba.cloud.ai.graph.*; import com.alibaba.cloud.ai.graph.checkpoint.BaseCheckpointSaver; import com.alibaba.cloud.ai.graph.checkpoint.savers.MemorySaver; import com.alibaba.cloud.ai.graph.checkpoint.config.SaverConfig;
import com.csust.eyediagnosis.workflow.contract.*; import com.csust.eyediagnosis.workflow.domain.*; import com.csust.eyediagnosis.workflow.graph.definition.*; import com.csust.eyediagnosis.workflow.graph.registry.InMemoryGraphDefinitionRegistry; import com.csust.eyediagnosis.workflow.graph.runtime.*; import com.csust.eyediagnosis.workflow.job.LeasedJobFence;
import org.junit.jupiter.api.Test; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*; import static org.junit.jupiter.api.Assertions.*;

/** Synthetic PR-05 runtime path: inference executes before its checkpoint and is not replayed by resume. */
class InferenceSegmentRuntimeTest {
    @Test void passAndAbstentionShareOneEnvelopeAcrossRuntimeResume() {
        for (InferenceOutcomeType outcome : List.of(InferenceOutcomeType.VALID_PREDICTION,InferenceOutcomeType.SAFETY_ABSTENTION,InferenceOutcomeType.TECHNICAL_FAILURE)) {
            AtomicInteger rpc=new AtomicInteger(), visionRuns=new AtomicInteger(); AtomicReference<VisionExposureOutput> exposure=new AtomicReference<>(); InferenceEnvelope envelope=envelope(outcome); GraphDefinitionHasher hasher=new Sha256GraphDefinitionHasher(); DiagnosisGraphDefinition definition=DiagnosisGraphDefinitionFactory.create(new GraphDefinitionManifest("i","i-v1","a",List.of(new GraphNodeSpec("START","BOUNDARY"),new GraphNodeSpec("inference","ACTION"),new GraphNodeSpec("vision","ACTION"),new GraphNodeSpec("END","BOUNDARY")),List.of(new GraphEdgeSpec("START","inference"),new GraphEdgeSpec("inference","vision"),new GraphEdgeSpec("vision","END")),List.of(),List.of(new GraphSegmentSpec(SegmentCode.INTAKE_INFERENCE_QUALITY,"START","inference"),new GraphSegmentSpec(SegmentCode.EVIDENCE_RETRIEVAL_VALIDATION,"vision","END")),List.of(),List.of("inference")),hasher); GraphDefinitionBinding binding=new GraphDefinitionBinding(definition.definitionVersion(),definition.definitionHash(),definition.actionVersion()); MemorySaver saver=new MemorySaver(); ExecutableDiagnosisGraphDefinition executable=new ExecutableDiagnosisGraphDefinition(){public GraphDefinitionBinding binding(){return binding;}public CompiledGraph compile(BaseCheckpointSaver ignored)throws Exception{return new StateGraph(KeyStrategy.builder().addStrategy(DefaultGraphSegmentRuntimeAdapter.BUSINESS_COMMIT_PLAN_KEY).build()).addNode("inference",state->{rpc.incrementAndGet();return CompletableFuture.completedFuture(Map.of(DefaultGraphSegmentRuntimeAdapter.BUSINESS_COMMIT_PLAN_KEY,plan()));}).addNode("vision",state->{visionRuns.incrementAndGet();exposure.set(new VisionExposureAction().execute(new VisionExposureInput(envelope),true));return CompletableFuture.completedFuture(Map.of());}).addEdge(StateGraph.START,"inference").addEdge("inference","vision").addEdge("vision",StateGraph.END).compile(CompileConfig.builder().saverConfig(SaverConfig.builder().register(saver).build()).interruptAfter("inference").build());}}; InMemoryGraphDefinitionRegistry registry=new InMemoryGraphDefinitionRegistry(List.of(definition),hasher); DefaultGraphSegmentRuntimeAdapter adapter=new DefaultGraphSegmentRuntimeAdapter(registry,new InMemoryExecutableGraphDefinitionRegistry(registry,List.of(executable)),()->saver,new ManifestGraphSegmentBoundaryResolver()); SegmentExecutionResult first=adapter.execute(new StartGraphSegmentRequest("wf",0,new LeasedJobFence("j","w","t",1,1),binding,SegmentCode.INTAKE_INFERENCE_QUALITY,0,new EmptySegmentInput())); assertEquals(1,rpc.get()); SegmentExecutionResult resumed=adapter.execute(new ResumeGraphSegmentRequest("wf",1,new LeasedJobFence("j2","w","t2",1,1),binding,SegmentCode.EVIDENCE_RETRIEVAL_VALIDATION,0,first.recoveryToken(),new EmptySegmentInput())); assertEquals(GraphRuntimeDisposition.COMPLETED,resumed.disposition()); assertEquals(1,rpc.get());assertEquals(1,visionRuns.get()); if(outcome==InferenceOutcomeType.VALID_PREDICTION)assertEquals(PredictionExposureStatus.AVAILABLE,exposure.get().exposureStatus());else assertNull(exposure.get().predictionProjection()); }
    }
    private static SegmentBusinessCommitPlan plan(){return new SegmentBusinessCommitPlan(WorkflowStatus.RUNNING,SegmentCode.INTAKE_INFERENCE_QUALITY,ExplanationPublicationStatus.NONE,PredictionExposureStatus.NOT_AVAILABLE,null,null,new NoBusinessDelta(),new WorkflowEventDraft("SEGMENT","SYSTEM","test",null,null));}
    private static InferenceEnvelope envelope(InferenceOutcomeType outcome){PredictionSnapshot p=outcome==InferenceOutcomeType.VALID_PREDICTION?new PredictionSnapshot("DR",.8,.2):null; SafetyAbstentionReasonCode a=outcome==InferenceOutcomeType.SAFETY_ABSTENTION?SafetyAbstentionReasonCode.OOD:null; TechnicalFailureCode f=outcome==InferenceOutcomeType.TECHNICAL_FAILURE?TechnicalFailureCode.GRPC_TIMEOUT:null;return new InferenceEnvelope("wf",0,"file:/x","d","image/png",new ImageQualitySnapshot(100,false,Set.of()),outcome,p,a,f,new OodSnapshot(a==SafetyAbstentionReasonCode.OOD,"IN_DISTRIBUTION",.1),new CalibrationSnapshot("CALIBRATED",.8),"v",outcome==InferenceOutcomeType.TECHNICAL_FAILURE?"not-provided":"sha","p","policy","2026-01-01T00:00:00Z");}
}
